require_once '../includes/security.php';start_secure_session();require_roles(['admin']);require_csrf();require '../includes/db.php';require_once '../includes/docx_case_import.php';$f=$_FILES['case_document']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>10*1024*1024||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='docx'){header('Location: ../auth/admin/cases/import.php?error=invalid_file');exit;}$hash=hash_file('sha256',$f['tmp_name']);$stmt=$conn->prepare('SELECT COUNT(*) FROM import_batches WHERE source_hash=?');$stmt->bind_param('s',$hash);$stmt->execute();if((int)$stmt->get_result()->fetch_row()[0]){header('Location: ../auth/admin/cases/import.php?error=duplicate_file');exit;}$owner=normalize_source_text($_POST['owning_tribe']??null);if(!$owner){header('Location: ../auth/admin/cases/import.php?error=ownership_required');exit;}$dir=sys_get_temp_dir().DIRECTORY_SEPARATOR.'geospatial_private_imports';if(!is_dir($dir))mkdir($dir,0700,true);$token=bin2hex(random_bytes(24));$path=$dir.DIRECTORY_SEPARATOR.$token.'.docx';move_uploaded_file($f['tmp_name'],$path);try{$preview=docx_case_preview($conn,$path);}catch(Throwable$e){@unlink($path);error_log($e->getMessage());header('Location: ../auth/admin/cases/import.php?error=parse_failed');exit;}$_SESSION['case_import_preview']=['token'=>$token,'path'=>$path,'hash'=>$hash,'name'=>basename($f['name']),'ownership'=>$owner,'preview'=>$preview,'created'=>time()];header('Location: ../auth/admin/cases/import.php?preview=1');
